#ifndef DECENTRALIZED_DTN_LOGISTIC_H
#define DECENTRALIZED_DTN_LOGISTIC_H

#include <stdint.h>
#include <stdbool.h>

#ifndef LOCAL_DECISION_FEATURES_DEF
#define LOCAL_DECISION_FEATURES_DEF
struct LocalDecisionFeatures {
    uint8_t  peer_is_destination;
    uint32_t packet_size_bytes;
    uint8_t  packet_priority;
    float    remaining_ttl_ratio;
    uint16_t packet_hops;
    uint32_t transfer_duration_ms;
    uint32_t contact_elapsed_ms;
    uint32_t estimated_remaining_contact_ms;
    uint8_t  estimated_transfer_fits;
    float    local_buffer_utilization;
    uint16_t peer_encounter_frequency;
};
#endif // LOCAL_DECISION_FEATURES_DEF

/**
 * Evaluates logistic regression logit: z > 0 corresponds to probability > 0.5.
 * Eliminates expensive exp() calculation on embedded MCU.
 */
inline bool decide_forwarding_logistic_regression(const LocalDecisionFeatures& features) {
    float logit = -0.509377f;
    logit += 0.448007f * ((features.peer_is_destination - 0.002105f) / 0.045831f);
    logit += 0.000000f * ((features.packet_size_bytes - 10000.000000f) / 1.000000f);
    logit += -0.002953f * ((features.packet_priority - 2.021492f) / 0.864929f);
    logit += 0.266228f * ((features.remaining_ttl_ratio - 0.785084f) / 0.613800f);
    logit += 0.000000f * ((features.packet_hops - 0.000000f) / 1.000000f);
    logit += 0.000000f * ((features.transfer_duration_ms - 90.000000f) / 1.000000f);
    logit += 0.000000f * ((features.contact_elapsed_ms - 0.000000f) / 1.000000f);
    logit += -0.618382f * ((features.estimated_remaining_contact_ms - 70618.508409f) / 191761.082691f);
    logit += 0.020005f * ((features.estimated_transfer_fits - 0.998473f) / 0.039052f);
    logit += -0.115753f * ((features.local_buffer_utilization - 0.029148f) / 0.012853f);
    logit += -0.172871f * ((features.peer_encounter_frequency - 5.416839f) / 4.973206f);
    return (logit > 0.0f);
}

#endif // DECENTRALIZED_DTN_LOGISTIC_H
